<script setup>


import {computed,ref,onMounted} from 'vue'
import {nodeOptions} from '../../apicenter/model.js'
import HelpTip from '../../shared/components/HelpTip.vue'
import {splitSQLNode} from '../deliveryStages.js'
import {randomUUID} from '../../shared/uuid.js'


import OperationNodeFields from './OperationNodeFields.vue'

import {nodeKindLabel, nodeTypeWarning} from '../nodePresentation.js'
const props=defineProps({ compact:Boolean,research:Boolean,approvalsOnly:Boolean,locked:Boolean,lockRecords:Boolean,requiredIds:{type:Array,default:()=>[]},nodes: { type: Array, default: () => [] }, apps: { type: Array, default: () => [] }, changes: { type: Array, default: () => [] }, users:{type:Array,default:()=>[]}, disabled: Boolean })
defineEmits(['locate-content'])
const researchKinds=[{value:'manual',label:'人工确认'},{value:'approval',label:'人工审批'},{value:'code-prepare',label:'自动合并并构建'},{value:'code-verify',label:'核对人工合入并构建'},{value:'verify',label:'独立验证（构建后）'}]
const builtinKinds = [{value:'approval',label:'人工审核'},{value:'deploy',label:'发布应用'},{value:'manual',label:'人工确认'},{value:'mysql',label:'SQL / 数据同步变更'},{value:'nacos',label:'Nacos 配置'},{value:'redis',label:'Redis 命令'},{value:'verify',label:'独立验证'},{value:'script',label:'交付脚本'}]
const pluginProviders=ref([]),pluginLoading=ref(false),pluginError=ref('')
async function refreshPlugins(){pluginLoading.value=true;pluginError.value='';try{const r=await fetch('/api/workflow-node-providers');if(!r.ok)throw Error('插件节点读取失败');pluginProviders.value=await r.json()}catch(e){pluginError.value=e.message}finally{pluginLoading.value=false}}
onMounted(()=>{if(!props.research&&!props.approvalsOnly)refreshPlugins()})
const kinds=computed(()=>[...builtinKinds,...nodeOptions(pluginProviders.value,props.nodes)])
const pluginDescriptor=n=>pluginProviders.value.find(p=>p.id===n.extension?.provider)?.nodes?.find(d=>d.key===n.extension?.node_key)||n.extension?.descriptor
const nodeTypeValue=n=>n.kind==='extension'?`extension@${n.extension?.provider}@${n.extension?.node_key}`:n.kind
function openDocumentSources(n){const d=pluginDescriptor(n),hash='#'+(d?.binding_path||'/documents')+(n.service?'?service='+encodeURIComponent(n.service):'');if(window.parent!==window)window.parent.postMessage({type:'workspace.open',plugin:'api-center',hash},location.origin);else window.open('/api/plugins/api-center/ui'+hash,'_blank','noopener')}
const required=n=>props.requiredIds.includes(n.id)
const recordLocked=n=>props.lockRecords&&n.kind==='manual'&&n.change_ids?.length
function canMove(nodes,i,j){if(props.research)return j>=0&&j<nodes.length;return j>=0&&j<nodes.length&&!required(nodes[i])&&!required(nodes[j])&&nodes[i].kind===nodes[j].kind || j>=0&&j<nodes.length&&!required(nodes[i])&&!required(nodes[j])&&nodes[i].kind!=='approval'&&nodes[j].kind!=='approval'}
function move(nodes,i,delta){const j=i+delta;if(canMove(nodes,i,j))[nodes[i],nodes[j]]=[nodes[j],nodes[i]]}
let dragged=-1
function drop(nodes,j){if(canMove(nodes,dragged,j)){const [n]=nodes.splice(dragged,1);nodes.splice(j,0,n)}dragged=-1}
function addReviews(nodes){nodes.unshift(...['开发负责人审核','测试审核','项目管理审核'].map(name=>({id:'review-'+randomUUID().slice(0,20),kind:'approval',name,approvers:[],approval_mode:'any'})))}
function changeNodeKind(n,value){if(value.startsWith('extension@')){const [,provider,node_key]=value.split('@');n.kind='extension';n.extension={provider,node_key,parameters:{}};const option=kinds.value.find(k=>k.value===value);n.name=option?.label||'插件节点';delete n.monitor;delete n.script;delete n.verification;return}n.kind=value;delete n.extension;if(value!=='deploy')delete n.monitor;if(value!=='script')delete n.script;if(value!=='verify')delete n.verification;if(value==='verify'){n.verification=n.verification||{mode:'http',url:'',expected_status:200,timeout_seconds:10}}if(value==='script'){n.script=n.script||{host:'',content:'',arguments:[],timeout_seconds:60}}if(props.research&&['code-prepare','code-verify'].includes(value)&&!n.application_scope&&!Object.keys(n.policies||{}).length){n.application_scope='delivery';n.policies={}}if(props.research&&value==='manual'){n.assignee_source=n.assignee_source||'delivery_initiator';n.approval_mode=n.approval_mode||'all';n.instructions=n.instructions||'确认本次所选交付内容齐全且准确'}}
function add(nodes) { if(props.research){nodes.push({id:'node-'+randomUUID().slice(0,20),name:'人工确认',kind:'manual',instructions:'确认本次所选交付内容齐全且准确',approvers:[],assignee_source:'delivery_initiator',approval_mode:'all',policies:{}});return}nodes.push({id:'node-'+randomUUID().slice(0,20),name:'发布应用',kind:'deploy',service:'',instructions:''}) }

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {ref as _viewRef} from 'vue'
const expandedNodes=_viewRef([])
const splitSelections=ref({})
function splitStage(index){const node=props.nodes[index];const id='sql-stage-'+randomUUID().slice(0,16);if(splitSQLNode(props.nodes,index,splitSelections.value[node.id]||[],id)){splitSelections.value[node.id]=[];expandedNodes.value.push(id)}}

function expandNode(id,keys){expandedNodes.value=keys.length?[...new Set([...expandedNodes.value,id])]:expandedNodes.value.filter(key=>key!==id)}



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Badge,Button,Field,FieldLabel,Input,Spinner,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><fieldset :disabled="disabled" class="node-editor"><Accordion v-for="(n,i) in nodes" :key="n.id" :draggable="!disabled&&!required(n)" @dragstart="dragged=i" @dragover.prevent @drop.prevent="drop(nodes,i)" class="node-edit rounded-lg border px-4" type="multiple" :model-value="expandedNodes.includes(n.id)?['panel']:[]" @update:model-value="keys=>{expandNode(n.id,keys);if(compact&amp;&amp;keys.length)$emit('locate-content',n)}"><AccordionItem :value="String(&quot;panel&quot;)"><div class="flex min-w-0 items-center gap-2"><AccordionTrigger class="min-w-0 flex-1"><span :title="n.name||'未命名节点'" class="node-name">{{i+1}}. {{n.name||'未命名节点'}}</span><Badge :variant="(nodeTypeWarning(n)?'orange':n.kind==='approval'?'arcoblue':undefined)==='red'?'destructive':'secondary'">{{nodeKindLabel(n)}}{{nodeTypeWarning(n)?' · 类型待核对':''}}</Badge> <span v-if="!compact||required(n)||(n.service&&!n.name?.includes(n.service))">{{compact&&n.name?.includes(n.service)?'':n.service||''}} {{required(n)?' · 强制审核':''}}</span></AccordionTrigger><slot name="scope-action" :node="n"/><span v-if="!required(n)&&(!compact||canMove(nodes,i,i-1)||canMove(nodes,i,i+1))" @click.stop @keydown.stop class="summary-tools"><Button :aria-label="'上移 '+n.name" @click.stop.prevent="move(nodes,i,-1)" variant="ghost" size="sm" type="button" :disabled="(disabled||!canMove(nodes,i,i-1))">↑</Button><Button :aria-label="'下移 '+n.name" @click.stop.prevent="move(nodes,i,1)" variant="ghost" size="sm" type="button" :disabled="(disabled||!canMove(nodes,i,i+1))">↓</Button></span></div><AccordionContent force-mount v-show="expandedNodes.includes(n.id)"><p v-if="nodeTypeWarning(n)" role="status" class="node-warning">{{nodeTypeWarning(n)}}</p><div class="node-fields"><Field ><FieldLabel as="div">名称</FieldLabel><Input v-model="n.name" :disabled="disabled||required(n)||recordLocked(n)"/></Field><Field ><FieldLabel as="div">节点类型</FieldLabel><OptionPicker :model-value="nodeTypeValue(n)" @update:model-value="changeNodeKind(n,$event)" :disabled="disabled||locked||required(n)||recordLocked(n)" :options="research?researchKinds:approvalsOnly?kinds.filter(k=>k.value==='approval'):kinds" :style="{width:'100%',maxWidth:'100%'}"/></Field></div><Field v-if="['deploy','extension'].includes(n.kind)"><FieldLabel as="div">应用</FieldLabel><OptionPicker v-model="n.service" :disabled="disabled||locked" :options="apps" :all-label="n.kind==='deploy'?'范围内全部应用（每个应用仅发布一次）':'本次交付范围内全部应用'"  :style="{width:'100%',maxWidth:'100%'}"/></Field><template v-if="n.kind==='approval'"><div class="node-fields"><Field ><FieldLabel as="div">审批人</FieldLabel><OptionPicker v-model="n.approvers" multiple  :disabled="disabled||required(n)" :options="users" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">签署规则</FieldLabel><OptionPicker v-model="n.approval_mode" :disabled="disabled||required(n)" :options="[{value:'any',label:'或签：任一人通过'},{value:'all',label:'会签：全部通过'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field></div><small v-if="required(n)">此审核节点由目标环境策略生成，请通过环境审核设置调整。</small><small v-else>{{research?'只允许当前阶段审批；不能自审，提交后冻结规则。':'审核节点应放在执行节点之前；不能自审，提交后冻结规则。'}}</small></template><Field v-else-if="n.kind!=='deploy'&&!['code-prepare','code-verify','extension'].includes(n.kind)"><FieldLabel as="div">操作 / 确认说明</FieldLabel><Textarea v-model="n.instructions" :disabled="disabled||recordLocked(n)" :rows="({minRows:(2),maxRows:Math.max((2),16)}).minRows||4"/></Field><small v-if="recordLocked(n)">来自所选自定义记录；可调整处理顺序，内容请在变更中修改后重新选择范围。</small><template v-if="research&&n.kind==='manual'"><div class="node-fields"><Field ><FieldLabel as="div">确认人来源</FieldLabel><OptionPicker :disabled="disabled" v-model="n.assignee_source" :options="[{value:'delivery_initiator',label:'本次交付发起人（开发／测试）'},{value:'work_item_resolvers',label:'关联工作项解决人'},{value:'work_item_assignees',label:'当前指派人'},{value:'work_item_participants',label:'工作项参与人（不含仅关注者）'},{value:'change_submitters',label:'本次变更提交人'},{value:'specified',label:'指定人员'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">签署规则</FieldLabel><OptionPicker :disabled="disabled" v-model="n.approval_mode" :options="[{value:'all',label:'全部确认人完成'},{value:'any',label:'任一确认人完成'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="n.assignee_source==='specified'"><FieldLabel as="div">确认人员</FieldLabel><OptionPicker :disabled="disabled" v-model="n.approvers" multiple  :options="users" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">应用范围</FieldLabel><OptionPicker :disabled="disabled" v-model="n.service" :options="apps" all-label="本次范围全部应用"  :style="{width:'100%',maxWidth:'100%'}"/></Field></div><small v-if="n.assignee_source==='delivery_initiator'">由本次发起人核对所选团队变更，不要求原登记人逐次确认；仅限非受保护的开发／测试环境，正式审批另行处理。已创建的执行单保留原确认规则。</small></template><template v-if="research&&['code-prepare','code-verify'].includes(n.kind)"><Field><FieldLabel as="div">同时构建的应用数</FieldLabel><OptionPicker :model-value="n.build_concurrency||2" @update:model-value="n.build_concurrency=$event" :disabled="disabled" :options="[1,2,3,4,5,6,7,8].map(value=>({value,label:value===1?'1 · 串行':String(value)}))"/><small>仍受 Runner 并发容量限制；同一目标分支的合并顺序不变。</small></Field><p class="hint">应用范围：跟随本次交付</p><small>自动解析本次需要构建的代码应用；配置 / SQL 和已有制品应用不参与。优先使用“应用 → 环境”中的代码与制品策略。</small><Button v-if="!n.default_code_policy" @click="n.default_code_policy={mode:'integration',base_branch:'',target_branch:''}" variant="ghost" size="default" type="button">设置通用分支策略（可选）</Button><div v-else class="node-fields"><Field ><FieldLabel as="div">通用分支方式</FieldLabel><OptionPicker :disabled="disabled" v-model="n.default_code_policy.mode" :options="[{value:'integration',label:'常驻分支'},{value:'isolated',label:'独立发布分支'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="n.default_code_policy.mode==='isolated'"><FieldLabel as="div">基线分支</FieldLabel><Input :disabled="disabled" v-model="n.default_code_policy.base_branch" placeholder="明确的生产基线，如 main"/></Field><Field ><FieldLabel as="div">目标分支</FieldLabel><Input :disabled="disabled" v-model="n.default_code_policy.target_branch" placeholder="如 test、release/{version}、hotfix/{work_item}"/></Field><Button @click="delete n.default_code_policy" variant="ghost" size="default" type="button">仅使用应用环境策略</Button></div></template><Field v-if="['mysql','nacos','redis'].includes(n.kind)"><FieldLabel as="div">关联变更</FieldLabel><OptionPicker v-model="n.change_ids" multiple  :disabled="disabled||locked" :options="changes.filter(c=>c.kind===n.kind).map(c=>({value:c.id,label:'#'+c.id+' '+c.title}))" all-label="所选版本内该类型全部变更" :style="{width:'100%',maxWidth:'100%'}"/></Field><div v-if="n.kind==='mysql'&&n.change_ids?.length>1" class="sql-stage-split"><Field><FieldLabel as="div">拆分 SQL 阶段</FieldLabel><OptionPicker v-model="splitSelections[n.id]" multiple :disabled="disabled" :options="changes.filter(c=>n.change_ids.includes(c.id)).map(c=>({value:c.id,label:'#'+c.id+' '+c.title}))" placeholder="选择移到下一阶段的变更"/></Field><Button variant="outline" size="sm" type="button" :disabled="disabled||!splitSelections[n.id]?.length||splitSelections[n.id].length>=n.change_ids.length||nodes.length>=30" @click="splitStage(i)">拆为下一阶段</Button><small>拆分后可将阶段移到应用发布前后；每项变更只执行一次。</small></div><template v-if="n.kind==='extension'&&pluginDescriptor(n)?.configuration==='node-fields'"><Field v-for="field in pluginDescriptor(n).fields" :key="field.key"><FieldLabel as="div">{{field.label}}</FieldLabel><Input v-model="n.extension.parameters[field.key]" :disabled="disabled||locked"/></Field></template><div v-if="n.kind==='extension'" class="node-tools"><Badge variant="secondary">{{pluginProviders.find(p=>p.id===n.extension?.provider)?.name||n.extension?.provider}}<template v-if="n.extension?.provider_version"> · {{n.extension.provider_version}}</template></Badge><HelpTip text="插件声明节点，平台冻结版本与制品范围后执行。节点复用应用与环境配置。测试集和用例修订在预览时冻结；执行结果可查看原报告。"/><Button v-if="pluginDescriptor(n)?.configuration==='application-binding'" @click="openDocumentSources(n)" variant="ghost" size="default" type="button">{{pluginDescriptor(n)?.binding_label||'维护应用文档来源'}}</Button><Button @click="refreshPlugins" variant="ghost" size="default" type="button" :disabled="(pluginLoading)"><Spinner v-if="pluginLoading"/>刷新插件</Button><span v-if="pluginError" role="alert">{{pluginError}}</span></div><OperationNodeFields v-if="['deploy','verify','script'].includes(n.kind)" :node="n" :apps="apps" :users="users" :disabled="disabled||locked"/><p v-if="n.kind==='data-sync'" role="alert">独立数据同步节点尚不可执行。请在数据同步任务中对比、核对并冻结为 SQL 变更，再使用 SQL 节点。</p><Field v-if="n.kind!=='approval'&&!required(n)"><FieldLabel as="div">前置依赖（可选）</FieldLabel><OptionPicker v-model="n.depends_on" :disabled="disabled" multiple :options="nodes.slice(0,i).filter(v=>v.kind!=='approval').map(v=>({value:v.id,label:v.name}))" :style="{width:'100%',maxWidth:'100%'}"/></Field><div class="node-tools"><Button @click="move(nodes,i,-1)" variant="outline" size="sm" type="button" :disabled="(disabled||!canMove(nodes,i,i-1))">上移</Button><Button @click="move(nodes,i,1)" variant="outline" size="sm" type="button" :disabled="(disabled||!canMove(nodes,i,i+1))">下移</Button><Button @click="nodes.splice(i,1)" variant="outline" size="sm" type="button" :disabled="(disabled||locked||required(n)||recordLocked(n))">删除</Button></div></AccordionContent></AccordionItem></Accordion><Button v-if="!locked&&!research" @click="addReviews(nodes)" variant="outline" size="default" type="button" :disabled="(disabled||nodes.some(n=>n.kind==='approval'))">＋ 三阶段审核</Button><Button v-if="!research&&!approvalsOnly&&!locked" @click="refreshPlugins" variant="ghost" size="default" type="button" :disabled="(pluginLoading)"><Spinner v-if="pluginLoading"/>刷新插件节点</Button><Button v-if="!locked&&!approvalsOnly" @click="add(nodes)" variant="outline" size="default" type="button" :disabled="(disabled)">＋ 添加节点</Button><Button v-if="approvalsOnly" @click="nodes.push({id:'review-'+randomUUID().slice(0,20),kind:'approval',name:'审核阶段',approvers:[],approval_mode:'any'})" variant="outline" size="default" type="button" :disabled="(disabled)">＋ 审核阶段</Button></fieldset></template>
<style scoped>.node-editor{border:0;padding:0;margin:0;min-width:0}.node-edit{margin-bottom:10px}.node-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.node-edit [data-slot=field]{margin-top:12px}.sql-stage-split{display:grid;gap:10px;margin-top:16px}.sql-stage-split>button{justify-self:start}.node-tools{display:flex;gap:8px;margin-top:12px}@media(max-width:700px){.node-fields{grid-template-columns:1fr}}.node-warning{color:var(--warn)}.node-warning{font-size:.75rem;margin:10px 0 0}</style>
